import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = rb();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = rb();
        StringBuilder sb = new StringBuilder();
        while (c != -1 && c != ' ' && c != '\n' && c != '\r' && c != '\t') {
            sb.append((char) c);
            c = rb();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        int n = s.length();
        long answer = 0;
        // Centers 0..2n-2: even ones sit on a character, odd ones between two characters.
        for (int center = 0; center < 2 * n - 1; center++) {
            int left = center / 2, right = (center + 1) / 2;
            while (left >= 0 && right < n && s.charAt(left) == s.charAt(right)) {
                answer++;
                left--;
                right++;
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readToken() string {
	c, err := reader.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = reader.ReadByte()
	}
	var tok []byte
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		tok = append(tok, c)
		c, err = reader.ReadByte()
	}
	return string(tok)
}

func main() {
	s := readToken()
	n := len(s)
	answer := 0
	// Centers 0..2n-2: even ones sit on a character, odd ones between two characters.
	for center := 0; center < 2*n-1; center++ {
		left, right := center/2, (center+1)/2
		for left >= 0 && right < n && s[left] == s[right] {
			answer++
			left--
			right++
		}
	}
	fmt.Println(answer)
}
